   405	int _gnutls_check_cert_sanity(gnutls_x509_crt_t cert)
   406	{
   407	        int result = 0, version;
   408	        gnutls_datum_t exts;
   409	
   410	        if (cert->flags & GNUTLS_X509_CRT_FLAG_IGNORE_SANITY)
   411	                return 0;
   412	
   413	        /* enforce the rule that only version 3 certificates carry extensions */
   414	        result = gnutls_x509_crt_get_version(cert);
   415	        if (result < 0) {
   416	                gnutls_assert();
   417	                goto cleanup;
   418	        }
   419	
   420	        version = result;
   421	
   422	        if (version < 3) {
   423	                if (!cert->modified) {
   424	                        result = _gnutls_x509_get_raw_field2(cert->cert, &cert->der,
   425	                                "tbsCertificate.extensions", &exts);
   426	                        if (result >= 0 && exts.size > 0) {
   427	                                gnutls_assert();
   428	                                _gnutls_debug_log("error: extensions present in certificate with version %d\n", version);
   429	                                result = GNUTLS_E_X509_CERTIFICATE_ERROR;
   430	                                goto cleanup;
   431	                        }
   432	                } else {
   433	                        if (cert->use_extensions) {
   434	                                gnutls_assert();
   435	                                _gnutls_debug_log("error: extensions set in certificate with version %d\n", version);
   436	                                result = GNUTLS_E_X509_CERTIFICATE_ERROR;
   437	                                goto cleanup;
   438	                        }
   439	                }
   440	        }
   441	
   442	        if (version < 2) {
   443	                char id[128];
   444	                size_t id_size;
   445	
   446	                id_size = sizeof(id);
   447	                result = gnutls_x509_crt_get_subject_unique_id(cert, id, &id_size);
   448	                if (result >= 0 || result == GNUTLS_E_SHORT_MEMORY_BUFFER) {
   449	                        gnutls_assert();
   450	                        _gnutls_debug_log("error: subjectUniqueID present in certificate with version %d\n", version);
   451	                        result = GNUTLS_E_X509_CERTIFICATE_ERROR;
   452	                        goto cleanup;
   453	                }
   454	
   455	                id_size = sizeof(id);
   456	                result = gnutls_x509_crt_get_issuer_unique_id(cert, id, &id_size);
   457	                if (result >= 0 || result == GNUTLS_E_SHORT_MEMORY_BUFFER) {
   458	                        gnutls_assert();
   459	                        _gnutls_debug_log("error: subjectUniqueID present in certificate with version %d\n", version);
   460	                        result = GNUTLS_E_X509_CERTIFICATE_ERROR;
   461	                        goto cleanup;
   462	                }
   463	        }
   464	
   465	        if (gnutls_x509_crt_get_expiration_time(cert) == -1 ||
   466	            gnutls_x509_crt_get_activation_time(cert) == -1) {
   467	                gnutls_assert();
   468	                _gnutls_debug_log("error: invalid expiration or activation time in certificate\n");
   469	                result = GNUTLS_E_CERTIFICATE_TIME_ERROR;
   470	                goto cleanup;
   471	        }
   472	
   473	        result = 0;
   474	
   475	 cleanup:
   476	        return result;
   477	}
