   479	/**
   480	 * gnutls_x509_crt_import:
   481	 * @cert: The data to store the parsed certificate.
   482	 * @data: The DER or PEM encoded certificate.
   483	 * @format: One of DER or PEM
   484	 *
   485	 * This function will convert the given DER or PEM encoded Certificate
   486	 * to the native gnutls_x509_crt_t format. The output will be stored
   487	 * in @cert.
   488	 *
   489	 * If the Certificate is PEM encoded it should have a header of "X509
   490	 * CERTIFICATE", or "CERTIFICATE".
   491	 *
   492	 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   493	 *   negative error value.
   494	 **/
   495	int
   496	gnutls_x509_crt_import(gnutls_x509_crt_t cert,
   497	                       const gnutls_datum_t * data,
   498	                       gnutls_x509_crt_fmt_t format)
   499	{
   500	        int result;
   501	
   502	        if (cert == NULL) {
   503	                gnutls_assert();
   504	                return GNUTLS_E_INVALID_REQUEST;
   505	        }
   506	
   507	        if (cert->expanded) {
   508	                /* Any earlier _asn1_strict_der_decode will modify the ASN.1
   509	                   structure, so we need to replace it with a fresh
   510	                   structure. */
   511	                result = crt_reinit(cert);
   512	                if (result < 0) {
   513	                        gnutls_assert();
   514	                        goto cleanup;
   515	                }
   516	        }
   517	
   518	        /* If the Certificate is in PEM format then decode it
   519	         */
   520	        if (format == GNUTLS_X509_FMT_PEM) {
   521	                /* Try the first header */
   522	                result =
   523	                    _gnutls_fbase64_decode(PEM_X509_CERT2, data->data,
   524	                                           data->size, &cert->der);
   525	
   526	                if (result < 0) {
   527	                        /* try for the second header */
   528	                        result =
   529	                            _gnutls_fbase64_decode(PEM_X509_CERT,
   530	                                                   data->data, data->size,
   531	                                                   &cert->der);
   532	
   533	                        if (result < 0) {
   534	                                gnutls_assert();
   535	                                return result;
   536	                        }
   537	                }
   538	        } else {
   539	                result = _gnutls_set_datum(&cert->der, data->data, data->size);
   540	                if (result < 0) {
   541	                        gnutls_assert();
   542	                        return result;
   543	                }
   544	        }
   545	
   546	        cert->expanded = 1;
   547	        cert->modified = 0;
   548	
   549	        result =
   550	            _asn1_strict_der_decode(&cert->cert, cert->der.data, cert->der.size, NULL);
   551	        if (result != ASN1_SUCCESS) {
   552	                result = _gnutls_asn2err(result);
   553	                gnutls_assert();
   554	                goto cleanup;
   555	        }
   556	
   557	        result = compare_sig_algorithm(cert);
   558	        if (result < 0) {
   559	                gnutls_assert();
   560	                goto cleanup;
   561	        }
   562	
   563	        /* The following do not allocate but rather point to DER data */
   564	        result = _gnutls_x509_get_raw_field2(cert->cert, &cert->der,
   565	                                          "tbsCertificate.issuer.rdnSequence",
   566	                                          &cert->raw_issuer_dn);
   567	        if (result < 0) {
   568	                gnutls_assert();
   569	                goto cleanup;
   570	        }
   571	
   572	        result = _gnutls_x509_get_raw_field2(cert->cert, &cert->der,
   573	                                          "tbsCertificate.subject.rdnSequence",
   574	                                          &cert->raw_dn);
   575	        if (result < 0) {
   576	                gnutls_assert();
   577	                goto cleanup;
   578	        }
   579	
   580	        result = _gnutls_x509_get_raw_field2(cert->cert, &cert->der,
   581	                                          "tbsCertificate.subjectPublicKeyInfo",
   582	                                          &cert->raw_spki);
   583	        if (result < 0) {
   584	                gnutls_assert();
   585	                goto cleanup;
   586	        }
   587	
   588	        result = cache_alt_names(cert);
   589	        if (result < 0) {
   590	                gnutls_assert();
   591	                goto cleanup;
   592	        }
   593	
   594	        result = _gnutls_check_cert_sanity(cert);
   595	        if (result < 0) {
   596	                gnutls_assert();
   597	                goto cleanup;
   598	        }
   599	
   600	        /* Since we do not want to disable any extension
   601	         */
   602	        cert->use_extensions = 1;
   603	
   604	        return 0;
   605	
   606	      cleanup:
   607	        _gnutls_free_datum(&cert->der);
   608	        return result;
   609	}
